// ─── File: SealedDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.sealed;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class SealedDemo {
    private static final Logger log = Logger.getLogger(SealedDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeeCalculator calc = new FeeCalculator();
        List<Account> accounts = List.of(
            new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
            new CurrentAccount("CUR3001", "Priya Sharma", new BigDecimal("250000")),
            new HomeLoan("LN5001", "Rajesh Kumar", new BigDecimal("3000000")),
            new PromoAccount("PR7001", "Priya Sharma", new BigDecimal("50000")));

        for (Account a : accounts) {
            BigDecimal fee = calc.monthlyFee(a);
            log.info(() -> a.holder() + " (" + a.id() + ") monthly fee = Rs." + fee);
        }
    }
}

// ─── Would be in model/Account.java ───
// Sealed interface: only the three listed types may DIRECTLY implement it.
sealed interface Account permits SavingsAccount, CurrentAccount, LoanAccount {
    String id();
    String holder();
    BigDecimal balance();
}

// ─── Would be in model/SavingsAccount.java ───
// FINAL: concrete leaf, cannot be extended further.
final class SavingsAccount implements Account {
    private final String id; private final String holder; private final BigDecimal balance;
        SavingsAccount(String id, String holder, BigDecimal balance) { this.id=id;
        this.holder=holder
        this.balance=balance; }
    public String id() { return id; } public String holder() { return holder; } public BigDecimal balance() { return balance; }
}

// ─── Would be in model/CurrentAccount.java ───
// FINAL: concrete leaf.
final class CurrentAccount implements Account {
    private final String id; private final String holder; private final BigDecimal balance;
        CurrentAccount(String id, String holder, BigDecimal balance) { this.id=id;
        this.holder=holder
        this.balance=balance; }
    public String id() { return id; } public String holder() { return holder; } public BigDecimal balance() { return balance; }
}

// ─── Would be in model/LoanAccount.java ───
// SEALED: continues the restriction with its own permits list.
sealed interface LoanAccount extends Account permits HomeLoan, PromoAccount { }

// ─── Would be in model/HomeLoan.java ───
// FINAL: concrete loan leaf.
final class HomeLoan implements LoanAccount {
    private final String id; private final String holder; private final BigDecimal balance;
        HomeLoan(String id, String holder, BigDecimal balance) { this.id=id;
        this.holder=holder
        this.balance=balance; }
    public String id() { return id; } public String holder() { return holder; } public BigDecimal balance() { return balance; }
}

// ─── Would be in model/PromoAccount.java ───
// NON-SEALED: deliberately reopens this branch for future extension.
non-sealed class PromoAccount implements LoanAccount {
    private final String id; private final String holder; private final BigDecimal balance;
        PromoAccount(String id, String holder, BigDecimal balance) { this.id=id;
        this.holder=holder
        this.balance=balance; }
    public String id() { return id; } public String holder() { return holder; } public BigDecimal balance() { return balance; }
}

// ─── Would be in service/FeeCalculator.java ───
class FeeCalculator {
    // EXHAUSTIVE switch over a sealed hierarchy — no default needed; compiler
    // verifies every permitted subtype is covered.
    BigDecimal monthlyFee(Account account) {
        return switch (account) {
            case SavingsAccount s -> BigDecimal.ZERO;                     // free
            case CurrentAccount c -> new BigDecimal("200.00");            // flat fee
            case HomeLoan h       -> h.balance().multiply(new BigDecimal("0.0005"))
                                        .setScale(2, java.math.RoundingMode.HALF_UP);
            case PromoAccount p   -> new BigDecimal("10.00");             // promo nominal
        };
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
